<script setup lang="ts">definePageMeta({layout:"admin",middleware:"admin"});const{data,refresh}=await useFetch("/api/admin/products");const values=reactive<Record<string,{quantityDelta:number;reason:string}>>({});function value(id:string){return values[id]??=( {quantityDelta:0,reason:"Penyesuaian admin"});}async function adjust(id:string){await $fetch(`/api/admin/inventory/${id}/adjustments`,{method:"POST",body:value(id)});values[id]={quantityDelta:0,reason:"Penyesuaian admin"};await refresh();}useSeoMeta({title:"Inventory"});</script>
<template><div><AdminPageHeader title="Inventory" description="Stok tersedia sudah memperhitungkan reservasi checkout aktif."/><div class="grid gap-3"><article v-for="product in data?.products" :key="product.id" class="surface grid items-center gap-4 p-5 md:grid-cols-[1fr_auto_auto]"><div><b>{{product.name}}</b><p class="text-xs text-slate-500">{{product.variant.sku}} · reserved {{product.variant.reservedStock}}</p></div><strong>{{product.variant.stockOnHand}} unit</strong><form class="flex gap-2" @submit.prevent="adjust(product.variant.id)"><input v-model.number="value(product.variant.id).quantityDelta" type="number" class="field w-24" required><AppButton type="submit">Adjust</AppButton></form></article></div></div></template>
